import csv
import io

def total_by_category(csv_text):
    totals = {}
    rows = csv.reader(io.StringIO(csv_text.strip()))
    next(rows)
    for row in rows:
        if not row:
            continue
        _, cat, price = row
        totals[cat] = round(totals.get(cat, 0.0) + float(price.replace(',', '')), 2)
    return totals

def intersect_intervals(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        lo, hi = max(a[i][0], b[j][0]), min(a[i][1], b[j][1])
        if lo <= hi:
            out.append([lo, hi])
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return out

def flatten_keys(d):
    out = {}
    def walk(node, prefix):
        if isinstance(node, dict):
            for k, v in node.items():
                walk(v, f'{prefix}.{k}' if prefix else str(k))
        elif isinstance(node, list):
            for i, v in enumerate(node):
                walk(v, f'{prefix}.{i}')
        else:
            out[prefix] = node
    walk(d, '')
    return out

