from collections import Counter

def topk_stable(items, k):
    counts = Counter(items)
    seen = {}
    for pos, x in enumerate(items):
        if x not in seen:
            seen[x] = pos
    ranked = sorted(counts, key=lambda x: (-counts[x], seen[x]))
    return ranked[:k]

def rle_encode(s):
    out, i = [], 0
    while i < len(s):
        if s[i] == '\\':
            out.append('\\\\')
            i += 1
            continue
        j = i
        while j < len(s) and s[j] == s[i] and s[j] != '\\':
            j += 1
        run = s[i:j]
        if len(run) >= 3:
            out.append('\\x%02d%s' % (len(run), s[i]))
        else:
            out.append(run)
        i = j
    return ''.join(out)

def rle_decode(s):
    out, i = [], 0
    while i < len(s):
        if s[i] == '\\':
            if s[i + 1] == '\\':
                out.append('\\')
                i += 2
            else:
                n = int(s[i + 2:i + 4])
                out.append(s[i + 4] * n)
                i += 5
        else:
            out.append(s[i])
            i += 1
    return ''.join(out)

from datetime import datetime

def max_errors_in_window(log_text, window_sec):
    fmt = '%Y-%m-%d %H:%M:%S'
    ts = []
    for line in log_text.strip().splitlines():
        parts = line.split(' ', 3)
        if len(parts) >= 3 and parts[2] == 'ERROR':
            ts.append(datetime.strptime(parts[0] + ' ' + parts[1], fmt).timestamp())
    ts.sort()
    best = 0
    j = 0
    for i, t in enumerate(ts):
        while ts[j] < t - window_sec:
            j += 1
        best = max(best, i - j + 1)
    return best

def strip_parens(s):
    out, depth = [], 0
    for ch in s:
        if ch == '(':
            if depth > 0:
                out.append(ch)
            depth += 1
        else:
            depth -= 1
            if depth > 0:
                out.append(ch)
    return ''.join(out)

def settle(balance, ops):
    b = float(balance)
    for kind, amt in ops:
        if kind == 'deposit':
            b += amt
            if amt >= 1000:
                b += 10
        else:
            b -= amt
            if b < 100:
                b -= 5
    return round(b, 2)
